def search_google(query, **_extra):
    import json, os, datetime, time, hashlib, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0332000" if __import__("os").path.isdir("./environment_mix/0332000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _norm_q(s):
        return " ".join(s.strip().split()).lower()

    def _gen_id(prefix):
        # Crockford base32, uppercase, no I/L/O/U
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        # 12 chars ~ 60 bits
        import random
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(12))

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # accept 'Z'
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ensure_dir(p):
        try:
            os.makedirs(p, exist_ok=True)
            return True
        except Exception:
            return False

    def _log(endpoint, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": _gen_id("wrl"),
            "endpoint": endpoint,
            "status": status,
            "latency_ms": int(latency_ms),
            "meta": meta or {},
            "created_at": _now(),
        }
        logs.append(row)
        _save("request_logs.json", logs)

    start = time.time()
    endpoint = "search_google"

    # Basic quota/rate limiting via request_logs.json (per-instance)
    # 60 req/min and 1000 req/day across all endpoints.
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    one_day_ago = now_dt - datetime.timedelta(days=1)
    rpm = 0
    rpd = 0
    for r in logs[-5000:]:
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=datetime.timezone.utc)
        if ts >= one_min_ago:
            rpm += 1
        if ts >= one_day_ago:
            rpd += 1
    if rpm >= 60:
        _log(endpoint, "RATE_LIMIT", (time.time() - start) * 1000, {"reason": "requests_per_minute"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    if rpd >= 1000:
        _log(endpoint, "QUOTA_EXCEEDED", (time.time() - start) * 1000, {"reason": "requests_per_day"})
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # Validate query
    if not isinstance(query, str):
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "query"})
        return _err("VALIDATION_ERROR", "query must be a string.", field="query")
    q_trim = query.strip()
    if len(q_trim) < 1:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "query"})
        return _err("VALIDATION_ERROR", "query must not be blank.", field="query")
    if len(query) > 2048:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "query"})
        return _err("VALIDATION_ERROR", "query is too long (max 2048).", field="query")

    normalized = _norm_q(query)
    if len(normalized) < 1 or len(normalized) > 2048:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "normalized_query"})
        return _err("VALIDATION_ERROR", "normalized query length invalid.", field="normalized_query")

    provider = "google"
    fp = hashlib.sha256((provider + "\n" + normalized).encode("utf-8")).hexdigest()

    # Dedup window: 10 minutes (configurable; enforced here)
    dedup_window = datetime.timedelta(minutes=10)
    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []
    existing = None
    for row in reversed(search_queries):
        if row.get("request_fingerprint") != fp:
            continue
        created = _parse_dt(row.get("created_at"))
        if not created:
            continue
        if created.tzinfo is None:
            created = created.replace(tzinfo=datetime.timezone.utc)
        if now_dt - created <= dedup_window:
            existing = row
            break

    if existing:
        # Return existing record and its stored results (idempotent within window)
        results = _load("search_results.json")
        if not isinstance(results, list):
            results = []
        qid = existing.get("id")
        res = [r for r in results if r.get("search_query_id") == qid]
        res.sort(key=lambda x: (x.get("rank") if isinstance(x.get("rank"), int) else 10**9, x.get("id", "")))
        payload = {
            "search": existing,
            "results": res,
            "meta": {"deduped": True, "result_count": len(res)},
        }
        _log(endpoint, "OK", (time.time() - start) * 1000, {"deduped": True, "search_query_id": qid})
        return payload

    # Create search_query row with lifecycle transitions queued->running->succeeded (or failed)
    now = _now()
    qid = _gen_id("wrq")
    qrow = {
        "id": qid,
        "query": query,
        "normalized_query": normalized,
        "status": "queued",
        "provider": "google",
        "result_count": 0,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "request_fingerprint": fp,
        "request_ip": _extra.get("request_ip") if isinstance(_extra.get("request_ip"), str) else None,
        "user_agent": _extra.get("user_agent") if isinstance(_extra.get("user_agent"), str) else None,
        "created_at": now,
        "updated_at": now,
    }
    search_queries.append(qrow)
    _save("search_queries.json", search_queries)

    # Transition to running
    qrow["status"] = "running"
    qrow["started_at"] = _now()
    qrow["updated_at"] = _now()
    _save("search_queries.json", search_queries)

    # Offline "search": derive deterministic pseudo-results from query terms, 0..10 results
    # (Real behavior would call Google; here we persist realistic shaped data deterministically.)
    def _is_abs_http_url(u):
        if not isinstance(u, str) or len(u) < 1 or len(u) > 4096:
            return False
        from urllib.parse import urlparse
        try:
            p = urlparse(u)
            return p.scheme in ("http", "https") and bool(p.netloc)
        except Exception:
            return False

    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []

    # Determine count deterministically: 5..10 based on fingerprint, but never > 100
    cnt = (int(fp[:2], 16) % 6) + 5  # 5-10
    # allow 0 results for some queries (e.g. very short/stopwordy) deterministically
    if len(normalized) <= 2:
        cnt = 0

    inserted = []
    used_urls = set()
    succeeded = True
    err_msg = None

    try:
        # Build base domain from hash
        base_dom_seed = int(fp[2:6], 16)
        domains = [
            "example.com",
            "example.org",
            "example.net",
            "wikipedia.org",
            "github.com",
            "news.ycombinator.com",
            "medium.com",
            "arxiv.org",
            "stackexchange.com",
            "docs.python.org",
        ]
        # rotate
        doms = domains[base_dom_seed % len(domains):] + domains[:base_dom_seed % len(domains)]
        for i in range(cnt):
            rank = i + 1
            dom = doms[i % len(doms)]
            slug_seed = hashlib.sha256((fp + f":{rank}").encode("utf-8")).hexdigest()[:12]
            # Ensure absolute http(s) URLs
            url = f"https://{dom}/search/{slug_seed}"
            if url in used_urls:
                continue
            used_urls.add(url)
            rid = _gen_id("wrr")
            rrow = {
                "id": rid,
                "search_query_id": qid,
                "rank": rank,
                "title": f"Result {rank} for {q_trim[:80]}",
                "url": url,
                "display_url": dom,
                "snippet": f"Captured snippet for '{q_trim[:120]}' (rank {rank}).",
                "provider_result_id": None,
                "created_at": _now(),
                "updated_at": _now(),
                "status": "active",
            }
            # Enforce url constraint
            if not _is_abs_http_url(rrow["url"]):
                continue
            inserted.append(rrow)

        # Enforce uniqueness per (search_query_id, rank) and (search_query_id, url)
        existing_pairs_rank = {(r.get("search_query_id"), r.get("rank")) for r in results}
        existing_pairs_url = {(r.get("search_query_id"), r.get("url")) for r in results}
        final_insert = []
        for r in inserted:
            pr = (r["search_query_id"], r["rank"])
            pu = (r["search_query_id"], r["url"])
            if pr in existing_pairs_rank or pu in existing_pairs_url:
                continue
            existing_pairs_rank.add(pr)
            existing_pairs_url.add(pu)
            final_insert.append(r)

        # Contiguity: if provider returns a full page (cnt>0), require ranks 1..len(final_insert)
        # Here we generate contiguous ranks, but if collisions removed some, trim to contiguous prefix.
        final_insert.sort(key=lambda x: x["rank"])
        contiguous = []
        expected = 1
        for r in final_insert:
            if r["rank"] != expected:
                break
            contiguous.append(r)
            expected += 1

        # Persist results
        if contiguous:
            results.extend(contiguous)
            _save("search_results.json", results)

        # Transition to succeeded
        qrow["status"] = "succeeded"
        qrow["result_count"] = len(contiguous)
        qrow["finished_at"] = _now()
        qrow["updated_at"] = _now()
        _save("search_queries.json", search_queries)

        payload = {
            "search": qrow,
            "results": contiguous,
            "meta": {"deduped": False, "result_count": len(contiguous)},
        }
        _log(endpoint, "OK", (time.time() - start) * 1000, {"search_query_id": qid, "result_count": len(contiguous)})
        return payload
    except Exception as e:
        succeeded = False
        err_msg = str(e)

    # Failure path: transition running->failed
    if not succeeded:
        # Validate transition
        if qrow.get("status") == "running":
            qrow["status"] = "failed"
            qrow["error_message"] = err_msg or "Search failed."
            qrow["finished_at"] = _now()
            qrow["updated_at"] = _now()
            _save("search_queries.json", search_queries)
        _log(endpoint, "FAILED", (time.time() - start) * 1000, {"search_query_id": qid, "error": err_msg})
        return _err("CONFLICT", "Search execution failed.", search_query_id=qid, detail=err_msg)

def visit_page(url, takeScreenshot=None, **_extra):
    import json, os, datetime, time, hashlib
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0332000" if __import__("os").path.isdir("./environment_mix/0332000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(12))

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("wrl"),
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int(latency_ms),
                "meta": meta or {},
                "created_at": _now(),
            }
        )
        _save("request_logs.json", logs)

    start = time.time()
    endpoint = "visit_page"

    # Rate/quota limiting
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    one_day_ago = now_dt - datetime.timedelta(days=1)
    rpm = 0
    rpd = 0
    for r in logs[-5000:]:
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=datetime.timezone.utc)
        if ts >= one_min_ago:
            rpm += 1
        if ts >= one_day_ago:
            rpd += 1
    if rpm >= 60:
        _log(endpoint, "RATE_LIMIT", (time.time() - start) * 1000, {"reason": "requests_per_minute"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")
    if rpd >= 1000:
        _log(endpoint, "QUOTA_EXCEEDED", (time.time() - start) * 1000, {"reason": "requests_per_day"})
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.")

    # Validate inputs
    if not isinstance(url, str):
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "url"})
        return _err("VALIDATION_ERROR", "url must be a string.", field="url")
    if len(url) < 1 or len(url) > 4096:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "url"})
        return _err("VALIDATION_ERROR", "url length must be between 1 and 4096.", field="url")
    try:
        p = urlparse(url)
    except Exception:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "url"})
        return _err("VALIDATION_ERROR", "Invalid URL.", field="url")
    if p.scheme not in ("http", "https") or not p.netloc:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "url"})
        return _err("VALIDATION_ERROR", "URL must be absolute with http/https scheme.", field="url")

    if takeScreenshot is None:
        takeScreenshot = False
    if not isinstance(takeScreenshot, bool):
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "takeScreenshot"})
        return _err("VALIDATION_ERROR", "takeScreenshot must be boolean.", field="takeScreenshot")

    # Optional provenance from _extra
    source_search_query_id = _extra.get("source_search_query_id")
    source_search_result_id = _extra.get("source_search_result_id")
    if source_search_query_id is not None and not isinstance(source_search_query_id, str):
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "source_search_query_id"})
        return _err("VALIDATION_ERROR", "source_search_query_id must be a string.", field="source_search_query_id")
    if source_search_result_id is not None and not isinstance(source_search_result_id, str):
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "source_search_result_id"})
        return _err("VALIDATION_ERROR", "source_search_result_id must be a string.", field="source_search_result_id")
    if source_search_result_id is not None and source_search_query_id is None:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "source_search_result_id"})
        return _err("VALIDATION_ERROR", "source_search_result_id requires source_search_query_id.", field="source_search_result_id")

    # Verify referenced search result relationship if provided
    if source_search_query_id is not None:
        sq = _load("search_queries.json")
        if not isinstance(sq, list):
            sq = []
        if not any(r.get("id") == source_search_query_id for r in sq):
            _log(endpoint, "NOT_FOUND", (time.time() - start) * 1000, {"field": "source_search_query_id"})
            return _err("NOT_FOUND", "source_search_query_id not found.", field="source_search_query_id")

    if source_search_result_id is not None:
        sr = _load("search_results.json")
        if not isinstance(sr, list):
            sr = []
        rr = None
        for r in sr:
            if r.get("id") == source_search_result_id:
                rr = r
                break
        if rr is None:
            _log(endpoint, "NOT_FOUND", (time.time() - start) * 1000, {"field": "source_search_result_id"})
            return _err("NOT_FOUND", "source_search_result_id not found.", field="source_search_result_id")
        if rr.get("search_query_id") != source_search_query_id:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "source_search_result_id"})
            return _err(
                "VALIDATION_ERROR",
                "source_search_result_id does not belong to source_search_query_id.",
                field="source_search_result_id",
            )

    visits = _load("page_visits.json")
    if not isinstance(visits, list):
        visits = []

    vid = _gen_id("wrv")
    now = _now()
    vrow = {
        "id": vid,
        "source_search_query_id": source_search_query_id,
        "source_search_result_id": source_search_result_id,
        "url": url,
        "final_url": url,
        "take_screenshot": takeScreenshot,
        "status": "queued",
        "http_status": None,
        "content_type": None,
        "content_length_bytes": None,
        "title": None,
        "extracted_text": None,
        "extracted_html": None,
        "extraction_metadata": None,
        "error_message": None,
        "started_at": None,
        "finished_at": None,
        "created_at": now,
        "updated_at": now,
    }
    visits.append(vrow)
    _save("page_visits.json", visits)

    # queued -> fetching
    vrow["status"] = "fetching"
    vrow["started_at"] = _now()
    vrow["updated_at"] = _now()
    _save("page_visits.json", visits)

    # "Fetch" offline: synthesize deterministic extraction for http(s) URLs
    try:
        # fetching -> extracting
        vrow["status"] = "extracting"
        vrow["http_status"] = 200
        vrow["content_type"] = "text/html; charset=utf-8"
        # deterministic content size and text
        h = hashlib.sha256(url.encode("utf-8")).hexdigest()
        content_len = (int(h[:6], 16) % 200000) + 800  # 800..200800
        vrow["content_length_bytes"] = content_len
        vrow["updated_at"] = _now()
        _save("page_visits.json", visits)

        # extracting -> succeeded
        title = f"Captured page: {p.netloc}"
        text = f"Offline extracted text for {url}\n\nFingerprint: {h}\n"
        vrow["title"] = title
        vrow["extracted_text"] = text
        vrow["extracted_html"] = f"<html><head><title>{title}</title></head><body><p>{text}</p></body></html>"
        vrow["extraction_metadata"] = {"host": p.netloc, "path": p.path, "hash": h}
        vrow["status"] = "succeeded"
        vrow["finished_at"] = _now()
        vrow["updated_at"] = _now()
        _save("page_visits.json", visits)

    except Exception as e:
        # extracting/fetching -> failed
        vrow["status"] = "failed"
        vrow["error_message"] = str(e)
        vrow["finished_at"] = _now()
        vrow["updated_at"] = _now()
        _save("page_visits.json", visits)
        _log(endpoint, "FAILED", (time.time() - start) * 1000, {"page_visit_id": vid, "error": str(e)})
        return {"visit": vrow, "screenshot": None}

    # If take_screenshot and succeeded, enqueue at least one screenshot
    screenshot_row = None
    if vrow["take_screenshot"] and vrow["status"] == "succeeded":
        # Enforce retention/quota: total stored screenshot bytes in last 24h <= 50MB
        limit_bytes = 50 * 1024 * 1024
        ss = _load("screenshots.json")
        if not isinstance(ss, list):
            ss = []
        total = 0
        cutoff = now_dt - datetime.timedelta(days=1)
        for r in ss:
            if r.get("status") != "stored":
                continue
            ts = _parse_dt(r.get("created_at"))
            if not ts:
                continue
            if ts.tzinfo is None:
                ts = ts.replace(tzinfo=datetime.timezone.utc)
            if ts < cutoff:
                continue
            b = r.get("byte_size")
            if isinstance(b, int) and b > 0:
                total += b
        # estimated new screenshot size
        new_size = (int(hashlib.sha256((vid + ":png").encode("utf-8")).hexdigest()[:6], 16) % 900000) + 100000
        if total + new_size > limit_bytes:
            _log(endpoint, "QUOTA_EXCEEDED", (time.time() - start) * 1000, {"reason": "screenshot_storage_bytes"})
            return _err("QUOTA_EXCEEDED", "Screenshot storage quota exceeded for the retention window.")

        # Create screenshots row and simulate lifecycle
        sid = _gen_id("wrs")
        created = _now()
        storage_backend = "local"
        image_format = "png"
        storage_key = f"screenshots/{sid}.{image_format}"
        screenshot_row = {
            "id": sid,
            "page_visit_id": vid,
            "status": "queued",
            "image_format": image_format,
            "storage_backend": storage_backend,
            "storage_key": storage_key,
            "byte_size": None,
            "width_px": None,
            "height_px": None,
            "captured_at": None,
            "error_message": None,
            "created_at": created,
            "updated_at": created,
        }
        ss.append(screenshot_row)
        _save("screenshots.json", ss)

        # queued -> capturing
        screenshot_row["status"] = "capturing"
        screenshot_row["updated_at"] = _now()
        _save("screenshots.json", ss)

        # capturing -> stored (simulate)
        screenshot_row["status"] = "stored"
        screenshot_row["byte_size"] = new_size
        screenshot_row["width_px"] = 1280
        screenshot_row["height_px"] = 720
        screenshot_row["captured_at"] = _now()
        screenshot_row["updated_at"] = _now()
        _save("screenshots.json", ss)

    _log(endpoint, "OK", (time.time() - start) * 1000, {"page_visit_id": vid, "took_screenshot": bool(screenshot_row)})
    return {"visit": vrow, "screenshot": screenshot_row}

def take_screenshot(pageVisitId=None, imageFormat=None, storageBackend=None, **_extra):
    import json, os, datetime, time, re, random, hashlib, urllib.parse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0332000" if __import__("os").path.isdir("./environment_mix/0332000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulidish(n=14):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _log(endpoint, status_code, ok, error_code=None, error_message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        t1 = started if isinstance(started, (int, float)) else time.time()
        t2 = time.time()
        logs.append({
            "id": "wrl_" + _ulidish(12),
            "endpoint": endpoint,
            "status_code": int(status_code),
            "ok": bool(ok),
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "timestamp": _now(),
            "latency_ms": int(round((t2 - t1) * 1000)),
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = _now_dt()
        window_start = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs[-8000:]:
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=120)
        return None

    def _lifecycle_transition_ok(frm, to):
        graph = {
            "queued": ["capturing", "failed"],
            "capturing": ["stored", "failed"],
            "stored": [],
            "failed": [],
        }
        return to in graph.get(frm, [])

    def _quota_check_and_get_usage(stored_rows, window_days=7, limit_bytes=50 * 1024 * 1024):
        now_dt = _now_dt()
        window_start = now_dt - datetime.timedelta(days=int(window_days))
        total = 0
        for r in stored_rows:
            if r.get("status") != "stored":
                continue
            ts = _parse_dt(r.get("captured_at")) or _parse_dt(r.get("updated_at")) or _parse_dt(r.get("created_at"))
            if ts and ts >= window_start:
                bs = r.get("byte_size")
                if isinstance(bs, int) and bs > 0:
                    total += bs
        return total, limit_bytes

    t0 = time.time()
    endpoint = "take_screenshot"

    rl = _enforce_rate_limit()
    if rl:
        _log(endpoint, 429, False, rl["error"]["code"], rl["error"]["message"], meta={"pageVisitId": pageVisitId, "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
        return rl

    # Validate enums/types (relaxed id validation: accept any string; pattern validation only when it looks like a page-visit id)
    if imageFormat is None:
        imageFormat = "png"
    if storageBackend is None:
        storageBackend = "local"
    if not isinstance(imageFormat, str) or imageFormat not in ("png", "jpeg"):
        e = _err("VALIDATION_ERROR", "Unsupported imageFormat; must be one of: png, jpeg.", field="imageFormat", allowed=["png", "jpeg"])
        _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"pageVisitId": pageVisitId, "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
        return e
    if not isinstance(storageBackend, str) or storageBackend not in ("local", "s3"):
        e = _err("VALIDATION_ERROR", "Unsupported storageBackend; must be one of: local, s3.", field="storageBackend", allowed=["local", "s3"])
        _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"pageVisitId": pageVisitId, "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
        return e
    if pageVisitId is not None and not isinstance(pageVisitId, str):
        e = _err("VALIDATION_ERROR", "pageVisitId must be a string when provided.", field="pageVisitId")
        _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"pageVisitId": pageVisitId, "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
        return e

    # Resolve page_visit_id:
    page_visits = _load("page_visits.json")
    if not isinstance(page_visits, list):
        page_visits = []
    browser_sessions = _load("browser_sessions.json")
    if not isinstance(browser_sessions, list):
        browser_sessions = []

    chosen_pv = None
    resolved_from_session = False

    if pageVisitId:
        # Only enforce strict pattern if it starts with expected prefix; otherwise treat as "id not found" not validation.
        if pageVisitId.startswith("wrv_") and not re.match(r"^wrv_[0-9A-HJKMNP-TV-Z]{10,}$", pageVisitId):
            e = _err("VALIDATION_ERROR", "pageVisitId format is invalid (must match ^wrv_[0-9A-HJKMNP-TV-Z]{10,}$).", field="pageVisitId")
            _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"pageVisitId": pageVisitId, "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
            return e
        for pv in page_visits:
            if pv.get("id") == pageVisitId:
                chosen_pv = pv
                break
        if chosen_pv is None:
            e = _err("NOT_FOUND", "Page visit not found for provided pageVisitId.", id=pageVisitId)
            _log(endpoint, 404, False, e["error"]["code"], e["error"]["message"], meta={"pageVisitId": pageVisitId, "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
            return e
    else:
        # Use latest active session with a current page visit.
        active_sessions = [s for s in browser_sessions if s.get("status") == "active" and isinstance(s.get("current_page_visit_id"), str) and s.get("current_page_visit_id")]
        def _sess_key(s):
            ts = _parse_dt(s.get("last_activity_at")) or _parse_dt(s.get("updated_at")) or _parse_dt(s.get("created_at"))
            return ts or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        active_sessions.sort(key=_sess_key, reverse=True)

        for s in active_sessions:
            pv_id = s.get("current_page_visit_id")
            for pv in page_visits:
                if pv.get("id") == pv_id:
                    chosen_pv = pv
                    resolved_from_session = True
                    break
            if chosen_pv:
                break

        if chosen_pv is None:
            # Deterministic failure: create no screenshot row.
            e = _err("NOT_FOUND", "No active browser session with a current page visit. Provide pageVisitId or create/activate a session with a loaded page.", rule="take_screenshot requires browser_sessions.status='active' and current_page_visit_id set when pageVisitId is omitted")
            _log(endpoint, 404, False, e["error"]["code"], e["error"]["message"], meta={"resolved_from_session": False, "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
            return e

    # Enforce screenshot retention/quota (simple service-level window policy).
    screenshots = _load("screenshots.json")
    if not isinstance(screenshots, list):
        screenshots = []
    current_usage, limit_bytes = _quota_check_and_get_usage(screenshots, window_days=7, limit_bytes=50 * 1024 * 1024)
    # Estimate new screenshot size deterministically by format (kept small-ish); reject if would exceed.
    est_new = 350_000 if imageFormat == "jpeg" else 600_000
    if current_usage + est_new > limit_bytes:
        e = _err("QUOTA_EXCEEDED", "Screenshot storage quota exceeded for the current retention window.", window_days=7, limit_bytes=limit_bytes, used_bytes=current_usage)
        _log(endpoint, 429, False, e["error"]["code"], e["error"]["message"], meta={"page_visit_id": chosen_pv.get("id"), "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
        return e

    # Create screenshot row and drive lifecycle queued->capturing->stored
    now = _now()
    ss_id = "wrs_" + _ulidish(26)
    # Deterministic storage key
    digest = hashlib.sha256((ss_id + "|" + str(chosen_pv.get("id")) + "|" + imageFormat + "|" + storageBackend).encode("utf-8")).hexdigest()[:24]
    storage_key = f"screenshots/{chosen_pv.get('id')}/{ss_id}_{digest}.{imageFormat}"

    # Unique(storage_backend, storage_key)
    for r in screenshots:
        if r.get("storage_backend") == storageBackend and r.get("storage_key") == storage_key:
            # Extremely unlikely; be idempotent-ish by returning existing row
            _log(endpoint, 200, True, meta={"idempotent": True, "existing_id": r.get("id")}, started=t0)
            return r

    row = {
        "id": ss_id,
        "page_visit_id": chosen_pv.get("id"),
        "status": "queued",
        "image_format": imageFormat,
        "storage_backend": storageBackend,
        "storage_key": storage_key,
        "byte_size": None,
        "width_px": None,
        "height_px": None,
        "captured_at": None,
        "error_message": None,
        "created_at": now,
        "updated_at": now,
    }

    # queued -> capturing
    if not _lifecycle_transition_ok("queued", "capturing"):
        e = _err("INVALID_TRANSITION", "Illegal status transition per lifecycle rules (queued→capturing).", from_status="queued", to_status="capturing")
        _log(endpoint, 409, False, e["error"]["code"], e["error"]["message"], meta={"page_visit_id": chosen_pv.get("id")}, started=t0)
        return e
    row["status"] = "capturing"
    row["updated_at"] = now

    # capturing -> stored (deterministic success)
    if not _lifecycle_transition_ok("capturing", "stored"):
        e = _err("INVALID_TRANSITION", "Illegal status transition per lifecycle rules (capturing→stored).", from_status="capturing", to_status="stored")
        _log(endpoint, 409, False, e["error"]["code"], e["error"]["message"], meta={"page_visit_id": chosen_pv.get("id")}, started=t0)
        return e
    row["status"] = "stored"
    row["captured_at"] = now
    row["updated_at"] = now
    # Fill in plausible deterministic metadata.
    row["byte_size"] = est_new
    row["width_px"] = 1365
    row["height_px"] = 768

    screenshots.append(row)
    _save("screenshots.json", screenshots)

    # Touch browser session last_activity_at if used
    if resolved_from_session:
        changed = False
        for s in browser_sessions:
            if s.get("status") == "active" and s.get("current_page_visit_id") == chosen_pv.get("id"):
                s["last_activity_at"] = now
                s["updated_at"] = now
                changed = True
                break
        if changed:
            _save("browser_sessions.json", browser_sessions)

    _log(endpoint, 200, True, meta={"id": ss_id, "page_visit_id": chosen_pv.get("id"), "imageFormat": imageFormat, "storageBackend": storageBackend}, started=t0)
    return row

def list_search_queries(status=None, provider=None, requestFingerprint=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0332000" if __import__("os").path.isdir("./environment_mix/0332000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        return prefix + "_" + "".join(random.choice(alphabet) for _ in range(12))

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(endpoint, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": _gen_id("wrl"),
                "endpoint": endpoint,
                "status": status,
                "latency_ms": int(latency_ms),
                "meta": meta or {},
                "created_at": _now(),
            }
        )
        _save("request_logs.json", logs)

    start = time.time()
    endpoint = "list_search_queries"

    # Rate limiting
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    now_dt = datetime.datetime.now(datetime.timezone.utc)
    one_min_ago = now_dt - datetime.timedelta(minutes=1)
    rpm = 0
    for r in logs[-5000:]:
        ts = _parse_dt(r.get("created_at"))
        if not ts:
            continue
        if ts.tzinfo is None:
            ts = ts.replace(tzinfo=datetime.timezone.utc)
        if ts >= one_min_ago:
            rpm += 1
    if rpm >= 120:  # allow higher for listing
        _log(endpoint, "RATE_LIMIT", (time.time() - start) * 1000, {"reason": "requests_per_minute"})
        return _err("RATE_LIMIT", "Rate limit exceeded.")

    # Validate filters
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "status"})
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status")

    if provider is not None:
        if not isinstance(provider, str) or provider not in {"google"}:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "provider"})
            return _err("VALIDATION_ERROR", "Invalid provider filter.", field="provider")

    if requestFingerprint is not None and not isinstance(requestFingerprint, str):
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "requestFingerprint"})
        return _err("VALIDATION_ERROR", "requestFingerprint must be a string.", field="requestFingerprint")

    ca = None
    cb = None
    if createdAfter is not None:
        if not isinstance(createdAfter, str) or _parse_dt(createdAfter) is None:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "createdAfter"})
            return _err("VALIDATION_ERROR", "createdAfter must be an ISO 8601 datetime string.", field="createdAfter")
        ca = _parse_dt(createdAfter)
        if ca.tzinfo is None:
            ca = ca.replace(tzinfo=datetime.timezone.utc)

    if createdBefore is not None:
        if not isinstance(createdBefore, str) or _parse_dt(createdBefore) is None:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "createdBefore"})
            return _err("VALIDATION_ERROR", "createdBefore must be an ISO 8601 datetime string.", field="createdBefore")
        cb = _parse_dt(createdBefore)
        if cb.tzinfo is None:
            cb = cb.replace(tzinfo=datetime.timezone.utc)

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100.", field="limit")

    # Decode cursor: base64url of "created_at|id"
    cursor_created = None
    cursor_id = None
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string.", field="cursor")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            parts = raw.split("|", 1)
            if len(parts) != 2:
                raise ValueError("bad cursor")
            cursor_created = _parse_dt(parts[0])
            cursor_id = parts[1]
            if cursor_created is None or not cursor_id:
                raise ValueError("bad cursor")
            if cursor_created.tzinfo is None:
                cursor_created = cursor_created.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            _log(endpoint, "VALIDATION_ERROR", (time.time() - start) * 1000, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    rows = _load("search_queries.json")
    if not isinstance(rows, list):
        rows = []

    # Filter
    out = []
    for r in rows:
        if status is not None and r.get("status") != status:
            continue
        if provider is not None and r.get("provider") != provider:
            continue
        if requestFingerprint is not None and r.get("request_fingerprint") != requestFingerprint:
            continue
        rca = _parse_dt(r.get("created_at"))
        if not rca:
            continue
        if rca.tzinfo is None:
            rca = rca.replace(tzinfo=datetime.timezone.utc)
        if ca is not None and rca < ca:
            continue
        if cb is not None and rca >= cb:
            continue
        # Pagination: created_at desc, then id desc
        if cursor_created is not None:
            rid = r.get("id", "")
            if rca > cursor_created:
                continue
            if rca == cursor_created and rid >= cursor_id:
                continue
        out.append(r)

    # Sort created_at desc then id desc
    def _sort_key(r):
        dt = _parse_dt(r.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return (dt, r.get("id", ""))

    out.sort(key=_sort_key, reverse=True)

    total = len(out)
    page = out[:limit]
    has_more = total > limit

    next_cursor = None
    if has_more and page:
        last = page[-1]
        last_dt = last.get("created_at")
        last_id = last.get("id")
        if isinstance(last_dt, str) and isinstance(last_id, str):
            raw = f"{last_dt}|{last_id}".encode("utf-8")
            next_cursor = base64.urlsafe_b64encode(raw).decode("utf-8").rstrip("=")

    _log(endpoint, "OK", (time.time() - start) * 1000, {"returned": len(page), "has_more": has_more})
    return {
        "data": page,
        "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def get_search_query(id, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0332000" if __import__("os").path.isdir("./environment_mix/0332000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _dt_parse(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _iso_or_none(dt):
        if dt is None:
            return None
        try:
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        except Exception:
            return None

    def _log(endpoint, status_code, ok, error_code=None, error_message=None, meta=None, started=None):
        # Best-effort request log; never blocks response if logging fails.
        try:
            logs = _load("request_logs.json")
            if not isinstance(logs, list):
                logs = []
            t1 = started if started is not None else time.time()
            t2 = time.time()
            row = {
                "id": "wrl_" + _gen_ulidish(12),
                "endpoint": endpoint,
                "status_code": int(status_code),
                "ok": bool(ok),
                "error_code": error_code,
                "error_message": error_message,
                "meta": meta or {},
                "timestamp": _now(),
                "latency_ms": int(round((t2 - t1) * 1000)),
            }
            logs.append(row)
            _save("request_logs.json", logs)
        except Exception:
            return

    def _gen_ulidish(n=12):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        import random
        return "".join(random.choice(alphabet) for _ in range(n))

    t0 = time.time()
    endpoint = "get_search_query"

    # Validate input
    if not isinstance(id, str):
        _log(endpoint, 400, False, "VALIDATION_ERROR", "id must be a string", {"id": id}, t0)
        return _err("VALIDATION_ERROR", "id must be a string")
    if not re.match(r"^wrq_[0-9A-HJKMNP-TV-Z]{10,}$", id):
        _log(endpoint, 400, False, "VALIDATION_ERROR", "id has invalid format", {"id": id}, t0)
        return _err("VALIDATION_ERROR", "id has invalid format", field="id")

    # Ambient auth: if there is any tenant context at all, allow.
    # If an auth collection exists and marks all disabled, return UNAUTHORIZED.
    auth_rows = _load("api_keys.json")
    if isinstance(auth_rows, list) and auth_rows:
        any_active = False
        for r in auth_rows:
            if isinstance(r, dict) and (r.get("status") in (None, "active", "enabled")):
                any_active = True
                break
        if not any_active:
            _log(endpoint, 401, False, "UNAUTHORIZED", "No active credentials available", {"id": id}, t0)
            return _err("UNAUTHORIZED", "Not authorized")

    queries = _load("search_queries.json")
    if not isinstance(queries, list):
        queries = []
    q = None
    for row in queries:
        if isinstance(row, dict) and row.get("id") == id:
            q = row
            break
    if q is None:
        _log(endpoint, 404, False, "NOT_FOUND", "Search query not found", {"id": id}, t0)
        return _err("NOT_FOUND", "Search query not found")

    results = _load("search_results.json")
    if not isinstance(results, list):
        results = []
    linked = [r for r in results if isinstance(r, dict) and r.get("search_query_id") == id]
    linked.sort(key=lambda r: (r.get("rank") if isinstance(r.get("rank"), int) else 10**9, r.get("id") or ""))

    body = {
        "search_query": q,
        "results": linked,
        "result_count": len(linked),
    }
    _log(endpoint, 200, True, None, None, {"id": id, "result_count": len(linked)}, t0)
    return body

