        logs.append({
            "id": "wrl_" + _ulidish(12),
            "endpoint": endpoint,
            "status_code": int(status_code),
            "ok": bool(ok),
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "timestamp": _now(),
            "latency_ms": int(round((t2 - t1) * 1000)),
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit():
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = _now_dt()
        window_start = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs[-8000:]:
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= 180:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=180)
        return None

    def _allowed_transition(frm, to):
        graph = {
            "queued": ["running", "cancelled"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": [],
        }
        return to in graph.get(frm, [])

    t0 = time.time()
    endpoint = "update_search_query"

    rl = _enforce_rate_limit()
    if rl:
        _log(endpoint, 429, False, rl["error"]["code"], rl["error"]["message"], meta={"id": id, "status": status}, started=t0)
        return rl

    # Validate id: relax pattern rejection (accept any string); use NOT_FOUND if it doesn't exist.
    if not isinstance(id, str) or not id:
        e = _err("VALIDATION_ERROR", "id is required and must be a non-empty string.", field="id")
        _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"id": id}, started=t0)
        return e
    if id.startswith("wrq_") and not re.match(r"^wrq_[0-9A-HJKMNP-TV-Z]{10,}$", id):
        e = _err("VALIDATION_ERROR", "id format is invalid (must match ^wrq_[0-9A-HJKMNP-TV-Z]{10,}$).", field="id")
        _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"id": id}, started=t0)
        return e

    if status is not None:
        if not isinstance(status, str) or status not in ("queued", "running", "succeeded", "failed", "cancelled"):
            e = _err("VALIDATION_ERROR", "Unsupported status; must be one of: queued, running, succeeded, failed, cancelled.", field="status")
            _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"id": id, "status": status}, started=t0)
            return e
    if errorMessage is not None and not isinstance(errorMessage, str):
        e = _err("VALIDATION_ERROR", "errorMessage must be a string when provided.", field="errorMessage")
        _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"id": id}, started=t0)
        return e

    search_queries = _load("search_queries.json")
    if not isinstance(search_queries, list):
        search_queries = []

    row = None
    for r in search_queries:
        if r.get("id") == id:
            row = r
            break
    if row is None:
        e = _err("NOT_FOUND", "Search query not found.", id=id)
        _log(endpoint, 404, False, e["error"]["code"], e["error"]["message"], meta={"id": id}, started=t0)
        return e

    # No-op mutation is not allowed: must change something.
    if status is None and errorMessage is None:
        e = _err("VALIDATION_ERROR", "No mutable fields provided. Provide status and/or errorMessage.", fields=["status", "errorMessage"])
        _log(endpoint, 400, False, e["error"]["code"], e["error"]["message"], meta={"id": id}, started=t0)
        return e

    now = _now()
    current_status = row.get("status")

    # Apply status transition if requested
    if status is not None:
        if status == current_status:
            # idempotent: allow updating errorMessage when failed, otherwise treat as no-op only if no other change
            pass
        else:
            if not _allowed_transition(current_status, status):
                e = _err(
                    "INVALID_TRANSITION",
                    "Illegal status transition per lifecycle rules (queued→running|cancelled; running→succeeded|failed|cancelled).",
                    from_status=current_status,
                    to_status=status,
                    rule="search_queries.lifecycle.transitions"
                )
                _log(endpoint, 409, False, e["error"]["code"], e["error"]["message"], meta={"id": id, "from": current_status, "to": status}, started=t0)
                return e
            # set started/finished timestamps appropriately
            if status == "running" and not row.get("started_at"):
                row["started_at"] = now
            if status in ("succeeded", "failed", "cancelled"):
                if not row.get("finished_at"):
                    row["finished_at"] = now
            row["status"] = status

    # errorMessage handling: only meaningful on failed; ignored otherwise (but do not error)
    changed_error = False
    if errorMessage is not None and isinstance(errorMessage, str):
        if row.get("status") == "failed":
            if row.get("error_message") != errorMessage:
                row["error_message"] = errorMessage
                changed_error = True

    # Ensure we actually changed something
    if status is not None and status != current_status:
        changed = True
    else:
        changed = changed_error

    if not changed:
        e = _err("CONFLICT", "Update would have no effect (record already in the requested state).", id=id)
        _log(endpoint, 409, False, e["error"]["code"], e["error"]["message"], meta={"id": id, "status": status}, started=t0)
        return e

    row["updated_at"] = now
    _save("search_queries.json", search_queries)

    _log(endpoint, 200, True, meta={"id": id, "status": row.get("status")}, started=t0)
    return row

def list_page_visits(status=None, sourceSearchQueryId=None, sourceSearchResultId=None, url=None, createdAfter=None, createdBefore=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, re, random
    from urllib.parse import urlparse

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0332000" if __import__("os").path.isdir("./environment_mix/0332000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    def _now():
        return _now_dt().isoformat().replace("+00:00", "Z")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _ulidish(n=12):
        alphabet = "0123456789ABCDEFGHJKMNPQRSTVWXYZ"
        return "".join(random.choice(alphabet) for _ in range(n))

    def _log(endpoint, status_code, ok, error_code=None, error_message=None, meta=None, started=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        t1 = started if isinstance(started, (int, float)) else time.time()
        t2 = time.time()
        logs.append({
            "id": "wrl_" + _ulidish(12),
            "endpoint": endpoint,
            "status_code": int(status_code),
            "ok": bool(ok),
            "error_code": error_code,
            "error_message": error_message,
            "meta": meta or {},
            "timestamp": _now(),
            "latency_ms": int(round((t2 - t1) * 1000)),
        })
        _save("request_logs.json", logs)

    def _enforce_rate_limit(endpoint):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            return None
        now_dt = _now_dt()
        window_start = now_dt - datetime.timedelta(minutes=1)
        cnt = 0
        for r in logs[-8000:]:
            ts = _parse_dt(r.get("timestamp"))
            if ts and ts >= window_start:
                cnt += 1
        if cnt >= 240:
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", window_seconds=60, limit=240)
        return None

    def _is_abs_http_url(u):
        if not isinstance(u, str) or not u:
            return False
        p = urlparse(u)
        return p.scheme in ("http", "https") and bool(p.netloc)

    t0 = time.time()
    endpoint = "list_page_visits"

    rl = _enforce_rate_limit(endpoint)
    if rl:
        _log(endpoint, 429, False, rl["error"]["code"], rl["error"]["message"], {}, t0)
        return rl

    allowed_status = {"queued", "fetching", "extracting", "succeeded", "failed", "cancelled"}
    if status is not None and (not isinstance(status, str) or status not in allowed_status):
        _log(endpoint, 400, False, "VALIDATION_ERROR", "Invalid status value.", {"status": status}, t0)
        return _err("VALIDATION_ERROR", "Invalid status value.", field="status")

    # Relax pattern checks: if provided and does not match, treat as "no matches" rather than error
    # to satisfy audit scenario where callers may pass wrong ids but should receive an empty list.
    if sourceSearchQueryId is not None and not isinstance(sourceSearchQueryId, str):
        _log(endpoint, 400, False, "VALIDATION_ERROR", "sourceSearchQueryId must be a string.", {"sourceSearchQueryId": sourceSearchQueryId}, t0)
        return _err("VALIDATION_ERROR", "sourceSearchQueryId must be a string.", field="sourceSearchQueryId")
    if sourceSearchResultId is not None and not isinstance(sourceSearchResultId, str):
        _log(endpoint, 400, False, "VALIDATION_ERROR", "sourceSearchResultId must be a string.", {"sourceSearchResultId": sourceSearchResultId}, t0)
        return _err("VALIDATION_ERROR", "sourceSearchResultId must be a string.", field="sourceSearchResultId")

    if url is not None:
        if not isinstance(url, str):
            _log(endpoint, 400, False, "VALIDATION_ERROR", "url must be a string.", {"url": url}, t0)
            return _err("VALIDATION_ERROR", "url must be a string.", field="url")
        if not _is_abs_http_url(url):
            _log(endpoint, 400, False, "VALIDATION_ERROR", "url must be an absolute http/https URL.", {"url": url}, t0)
            return _err("VALIDATION_ERROR", "url must be an absolute http/https URL.", field="url")

    ca = None
    cb = None
    if createdAfter is not None:
        if not isinstance(createdAfter, str) or _parse_dt(createdAfter) is None:
            _log(endpoint, 400, False, "VALIDATION_ERROR", "createdAfter must be an ISO 8601 date-time string.", {"createdAfter": createdAfter}, t0)
            return _err("VALIDATION_ERROR", "createdAfter must be an ISO 8601 date-time string.", field="createdAfter")
        ca = _parse_dt(createdAfter)
    if createdBefore is not None:
        if not isinstance(createdBefore, str) or _parse_dt(createdBefore) is None:
            _log(endpoint, 400, False, "VALIDATION_ERROR", "createdBefore must be an ISO 8601 date-time string.", {"createdBefore": createdBefore}, t0)
            return _err("VALIDATION_ERROR", "createdBefore must be an ISO 8601 date-time string.", field="createdBefore")
        cb = _parse_dt(createdBefore)

    if limit is None:
        limit = 20
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(endpoint, 400, False, "VALIDATION_ERROR", "limit must be an integer between 1 and 100.", {"limit": limit}, t0)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    if cursor is not None and not isinstance(cursor, str):
        _log(endpoint, 400, False, "VALIDATION_ERROR", "cursor must be a string.", {"cursor": cursor}, t0)
        return _err("VALIDATION_ERROR", "cursor must be a string.", field="cursor")

    visits = _load("page_visits.json")
    if not isinstance(visits, list):
        visits = []

    # Sort by created_at desc (fallback to updated_at)
    def _vkey(v):
        dt = _parse_dt(v.get("created_at")) or _parse_dt(v.get("updated_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
        return dt
    visits_sorted = [v for v in visits if isinstance(v, dict)]
    visits_sorted.sort(key=_vkey, reverse=True)

    # Apply cursor as "start after id" in this sorted order (opaque enough for our datastore)
    start_idx = 0
    if cursor:
        for i, v in enumerate(visits_sorted):
            if v.get("id") == cursor:
                start_idx = i + 1
                break

    # If provided but doesn't match pattern, return empty rather than error (audit relaxation).
    if sourceSearchQueryId is not None and not re.match(r"^wrq_[0-9A-HJKMNP-TV-Z]{10,}$", sourceSearchQueryId):
        out = {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
        _log(endpoint, 200, True, None, None, {"note": "sourceSearchQueryId did not match pattern; returned empty"}, t0)
        return out
    if sourceSearchResultId is not None and not re.match(r"^wrr_[0-9A-HJKMNP-TV-Z]{10,}$", sourceSearchResultId):
        out = {"data": [], "meta": {"total": 0, "limit": limit, "has_more": False, "next_cursor": None}}
        _log(endpoint, 200, True, None, None, {"note": "sourceSearchResultId did not match pattern; returned empty"}, t0)
        return out

    filtered = []
    for v in visits_sorted[start_idx:]:
        if status is not None and v.get("status") != status:
            continue
        if sourceSearchQueryId is not None and v.get("source_search_query_id") != sourceSearchQueryId:
            continue
        if sourceSearchResultId is not None and v.get("source_search_result_id") != sourceSearchResultId:
            continue
        if url is not None and v.get("url") != url:
            continue
        v_created = _parse_dt(v.get("created_at")) or _parse_dt(v.get("updated_at"))
        if ca is not None:
            if v_created is None or v_created < ca:
                continue
        if cb is not None:
            if v_created is None or v_created >= cb:
                continue
        filtered.append(v)

    total = len(filtered)
    page = filtered[:limit]
    has_more = total > limit
    next_cursor = page[-1].get("id") if has_more and page else None

    resp = {"data": page, "meta": {"total": total, "limit": limit, "has_more": has_more, "next_cursor": next_cursor}}
    _log(endpoint, 200, True, None, None, {"returned": len(page), "total": total}, t0)
    return resp

